def entrypoint():
    from helper import TARGET_FINAL_RANK

    evaluator = Evaluator(path_name="init", max_depth=500)

    def optimize(evaluator: Evaluator):
        algorithm = DE(pop_size=36, variant="DE/rand/1/bin", CR=0.9, F=0.6)
        minimize(Problem(evaluator), algorithm, termination=("n_eval", N_EVAL), seed=17, verbose=False)

